def item(name, qty, price):
    return {"product_name": name, "qty": qty, "unit_price": price}


def add(
    number,
    text,
    items,
    *,
    language="mixed",
    family=None,
    customer=None,
    fee=None,
    note=None,
    tags=(),
    source="authored",
    rationale,
    alternatives=None,
    ambiguities=None,
    related=(),
):
    case_id = f"v2-dev-{number:02d}"
    rows.append(
        {
            "id": case_id,
            "family": family or case_id,
            "split": "development",
            "language": language,
            "tags": list(tags),
            "ambiguities": ambiguities or [],
            "text": text,
            "expected": {
                "customer": {
                    **dict.fromkeys(("name", "phone", "township", "address")),
                    **(customer or {}),
                },
                "items": items,
                "delivery_fee": fee,
                "note": note,
            },
            "alternatives": alternatives or {},
            "provenance": f"synthetic-adaptation; source={source}; development-only; provisional-labels; not-language-reviewed",
        }
    )
    annotations[case_id] = {
        "source_ids": [source],
        "review_status": "pending-independent-language-review",
        "label_notes": rationale,
        "related_v1_families": list(related),
    }


